// spec: .qa/e2e/specs/promo-filter.md
// seed: tests/seed.hunter_free.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_free.json') });

const SECTION = 'מסלול קידום והפצה';

test.describe('Promotion filter — jobs and tenders lists (#521d84)', () => {
  test('Same behaviour on /tenders @desktop @prod-safe #521d84', async ({ page }) => {
    const sidebar = page.getByRole('complementary');
    const section = sidebar.getByRole('button', { name: SECTION, exact: true });
    const option = (name: string) => sidebar.getByRole('checkbox', { name, exact: true });
    const openSection = async () => {
      if ((await section.getAttribute('aria-expanded')) !== 'true') await section.click();
      await expect(section).toHaveAttribute('aria-expanded', 'true');
    };
    const chip = page.getByRole('button', { name: 'הסרת הסינון: ללא קידום', exact: true });
    const count = page.getByText(/^\d+ תוצאות$/);
    const readCount = async () => Number((await count.innerText()).match(/\d+/)![0]);

    // 1. Open /tenders, open «מסלול קידום והפצה»
    await page.goto('/tenders');
    await expect(count).toBeVisible();
    await openSection();

    // Expected: «הכל» exists and is selected; «N תוצאות» shown
    await expect(option('הכל')).toBeChecked();
    await expect(option('ללא קידום')).not.toBeChecked();
    const n = await readCount();
    expect(n).toBeGreaterThan(0);
    expect(new URL(page.url()).searchParams.has('promo')).toBe(false);

    // 2. Choose «ללא קידום»
    await option('ללא קידום').click();

    // Expected: promo= in URL, count updated, removable chip shown
    await expect(page).toHaveURL(/[?&]promo=[^&]+/);
    await expect(chip).toBeVisible();
    await expect(chip).toContainText('×');
    await expect(option('ללא קידום')).toBeChecked();
    await expect(option('הכל')).not.toBeChecked();
    await expect.poll(readCount).toBeLessThanOrEqual(n);

    // 3. Remove the chip with «×»
    await chip.click();

    // Expected: back to «הכל», count N, no promo in URL
    await expect(chip).toHaveCount(0);
    await expect.poll(() => new URL(page.url()).searchParams.has('promo')).toBe(false);
    await expect.poll(readCount).toBe(n);
    await openSection();
    await expect(option('הכל')).toBeChecked();
  });
});
